function getColorShades(color: string): string[] {
  return [
    `var(--Segment-1, var(--display-${color}-scale-8))`,
    `var(--Segment-2, var(--display-${color}-scale-6))`,
    `var(--Segment-3, var(--display-${color}-scale-4))`,
    `var(--Segment-4, var(--display-${color}-scale-2))`,
    `var(--Segment-5, var(--display-${color}-scale-1))`,
    `var(--Segment-6, var(--display-${color}-scale-0))`,
  ]
}

function getBiColorShades(color: string): string[] {
  return [`var(--Segment-1, var(--display-${color}-scale-9))`, `var(--Segment-2, var(--display-${color}-scale-4))`]
}

// Mulit-color
export const greenShades = getColorShades('green')
export const purpleShades = getColorShades('purple')
export const blueShades = getColorShades('blue')
export const indigoShades = getColorShades('indigo')
export const orangeShades = getColorShades('orange')

// Bi-color
export const indigoBiColorShades = getBiColorShades('indigo')
export const greenBiColorShades = getBiColorShades('green')
export const purpleBiColorShades = getBiColorShades('purple')
