import {ChartCard} from '@github-ui/chart-card'
import ChartErrorState from './ChartErrorState'
import {ScreenWidth} from './utils/Utility'

export interface DonutChartData {
  name: string
  y: number
}

interface DonutChartProps {
  payload: DonutChartData[]
  title: string
  description?: string
  colors: string[]
}

export interface DonutChartPayload {
  data: DonutChartData[]
}

function DonutChart({payload, title, description, colors}: DonutChartProps) {
  if (!payload || payload.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const payloadWithColors = payload.map((data, index) => ({
    ...data,
    color: colors[index % colors.length], // Cycles through colors
  }))

  const series = [
    {
      type: 'pie',
      name: title,
      data: payloadWithColors,
    },
  ]

  return (
    <div className="height-full">
      <ChartCard size="medium" border padding="normal" visibleControls={false} className="width-full height-full">
        <ChartCard.Title as="h2">{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          series={series}
          tooltipOptions={{
            enabled: false, // Disable tooltip for simple donut charts
          }}
          plotOptions={{
            pie: {
              borderWidth: 3,
              borderColor: 'var(--bgColor-default)',
              borderRadius: 0,
              states: {
                hover: {
                  halo: null,
                },
              },
              dataLabels: {
                enabled: true,
                connectorColor: 'var(--borderColor-emphasis)',
                formatter() {
                  // `format` overrides the `formatter` property so used the formatter equivalent
                  // eslint-disable-next-line github/unescaped-html-literal
                  return `<span style="font:var(--text-caption-shorthand)">${this.point.name}</span><br/>
                          <span style="color:var(--fgColor-muted); font:var(--text-caption-shorthand)">${this.point.y?.toFixed(
                            1,
                          )}%</span>`
                },
                style: {
                  fontSize: 'var(--text-body-size-medium)',
                  color: 'var(--fgColor-default)',
                  textOutline: 'none',
                },
              },
            },
            series: {
              dataLabels: {
                enabled: true,
              },
              innerSize: '60%', // For donut chart
            },
          }}
          overrideOptionsNotRecommended={{
            responsive: {
              rules: [
                {
                  condition: {
                    maxWidth: ScreenWidth.xsmall,
                  },
                  chartOptions: {
                    plotOptions: {
                      pie: {
                        borderWidth: 0.5,
                        showInLegend: true,
                        dataLabels: {
                          padding: 0,
                          enabled: true,
                          formatter() {
                            return `${this.point.index + 1}`
                          },
                          style: {
                            fontWeight: 'normal',
                          },
                        },
                      },
                    },
                    legend: {
                      enabled: true,
                      layout: 'horizontal',
                      align: 'center',
                      verticalAlign: 'bottom',
                      labelFormatter() {
                        return `${this.index + 1} ${this.name}`
                      },
                    },
                  },
                },
              ],
            },
          }}
          type="pie"
        />
      </ChartCard>
    </div>
  )
}

export default DonutChart
